        line: pattern.line,
        detectedAtMs: now,
        description: `${pattern.line}: moderate avoidance (${(pattern.avoidanceRate * 100).toFixed(0)}%) with low defensive engagement — possible refusal to grow.`,
      });
    }
  }
}

