38:   altitudes: Record<Line, Stage>;
39:   centreOfGravity: Stage;
40:   thetaDecay: Record<Line, {
41:     lastExercisedAt: number;
42:     decayLevel: number;          // 0.0 (fresh) to 1.0 (critical)
43:     stage: Stage;                // the stage that is decaying
44:   }>;
45:   driveBalance: Record<Drive, number>;          // -1.0 to +1.0
46:   fixationRisk: Record<Drive, number>;          // 0.0 to 1.0
47:   shadowLedger: ShadowSignal[];                 // active/unresolved entries
48:   compoundShadows: CompoundShadow[];            // cross-line patterns
49:   polarityState: {
