51:     direction: 'STO' | 'STS' | null;
52:     crystallizationIndex: number;
53:     perLineProfiles: Record<Line, LinePolarityProfile>;
54:   };
55:   transformationReadiness: {
56:     linesAtEdge: number;
57:     shadowClearance: boolean;
58:     catalystSaturation: number;
59:     pendingTransformation: boolean;
60:     targetStage: Stage | null;
61:   };
62:   recentEncounterHistory: RecentEncounter[];     // last 10 encounters
63: }
64: 
65: interface RecentEncounter {
66:   moduleRef: { line: Line; stage: Stage };
67:   modality: GameModality;
68:   timestamp: number;
69:   outcome: 'completed' | 'avoided' | 'abandoned';
70: }
71: ```
72: 
73: ### 2.2 World state (from foundations/18)
